      "学术与考核": ["学部", "课程", "专业", "学习", "帝国考核", "毕业考", "最终考核"],
      "权力政治": ["派系", "传统派", "革新派", "中立", "学生会", "家族", "选举", "贵族"],
      "校园文化": ["社团", "活动", "作息", "舞会", "诗会", "辩论赛", "决斗季"],
      "规章制度": ["校规", "纪律", "决斗", "惩罚", "宵禁", "着装"],
      "人际关系": ["朋友", "对手", "导师", "马可", "西里斯", "康拉德"]
    },

    "内容精要": {
      "学院总纲": {
        "核心原则": "现实主义世界观，以校训'荣誉、责任、远见'为最高准则，名誉是硬通货。",
        "历史沿革": "帝国历378年由奥托大帝创立，旨在培养帝国精英，统一贵族教育。",
        "学生构成": "总计520名学生，70%贵族与30%平民奖学金生，年龄15-22岁，四年制。"
      },

      "地理与关键地点": {
        "建筑分区": "旧庭(哥特式传统)、新庭(蒸汽朋克工业)、主楼群(巴洛克式中心)。",
        "关键地标": "双子塔楼(时间中心)、静默之庭(知识圣殿)、荣耀厅(武力殿堂)、温室花园(社交舞台)、齿轮工坊(创新基地)、银溪码头(休闲场所)。"
      },

      "学术与考核": {
        "六大学部": "古典人文、法学与政治、军事战略、理工、经济、艺术。",
        "课程体系": "核心必修课(如帝国史、拉丁语) + 专业选修课 + 跨学部合作项目。",
        "帝国考核": "决定命运的最终评估，包含'综合笔试'、'实践能力评估'、'帝国政策辩论'和'危机管理模拟'四个部分。"
      },

      "权力与派系": {
        "三大派系": "传统派(保守，以斯尔芬登、德拉库尔家族为首)、革新派(进步，以沃兰斯基、法乌斯蒂安家族为首)、中立派(专业或艺术至上)。",
        "主要家族": "斯尔芬登(司法)、德拉库尔(军事)、沃兰斯基(金融)、法乌斯蒂安(科技)、瓦洛瓦(社交)等八大家族在学院各具影响力。",
        "学生会": "官方自治组织，是各派系博弈的主要政治舞台，掌握活动审批、经费分配等实权。"
      },

      "校园生活与年度传统": {
        "社团生态": "分为学术、艺术、体育竞技、特殊兴趣四大类，活动丰富。",
        "日常作息": "从清晨6点的军事晨训到午夜分级的宵禁，作息严格规律。",
        "年度传统": "春季的学院舞会、秋季的校际辩论赛、以及每年两次的受监督决斗季等。"
      },

      "规章与制度": {
        "核心准则": "严格的着装、礼仪与宵禁规定，公私行为界限分明。",
        "冲突解决": "严禁私下决斗。所有冲突需通过导师调解、学生法庭或受监督的荣誉决斗解决。",
        "奖惩体系": "分级的惩罚制度，从口头警告到开除学籍，贵族与平民在奖惩上略有区别。"
      },
